@prefix cdifd: <https://cdif.org/validation/0.1/shacl#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:Person ;
                    schema1:description "Draft generated by Claude (Anthropic) under human review, from analysis of ADA metadata records and the 14 Curtin University method-description documents attached to them. Parameter values and tier assignments are derived, not authored by the laboratory." ;
                    schema1:name "Claude assisted" ] ;
            sh:resultMessage "A Person should have a contactPoint (schema:ContactPoint or mailto: IRI)" ;
            sh:resultPath schema1:contactPoint ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape cdifd:contactPointProperty ] .

@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <ex:instrument/SEM> ;
            sh:resultMessage "An instrument should have an identifier (schema:identifier)." ;
            sh:resultPath schema1:identifier ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "An instrument should have an identifier (schema:identifier)." ;
                    sh:minCount 1 ;
                    sh:path schema1:identifier ;
                    sh:severity sh:Warning ] ] .

